  ('da735532-cb33-54aa-898c-9ddbfd9ea906'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un pont diviseur à vérifier","competence":"raisonner","situation":"Éloïse a monté un pont diviseur 5 V qui fournit la tension de référence de 2,5 V de la carte. Les deux résistances de 10 kΩ ont une tolérance de 5 %. Le cahier des charges demande 2,5 V à 0,15 V près.","documents":[{"id":"cir","type":"circuit","titre":"Le montage mesuré","source":"Schéma imaginé pour l’exercice","branches":[{"de":[0,0],"a":[0,6],"composant":"pile","nom":"5 V"},{"de":[0,0],"a":[8,0],"composant":"resistance","nom":"R1","id":"z1"},{"de":[8,0],"a":[8,6],"composant":"resistance","nom":"R2","id":"z2"},{"de":[8,0],"a":[12,0]},{"de":[8,6],"a":[12,6]},{"de":[12,0],"a":[12,6],"composant":"voltmetre","nom":"V","id":"z3"},{"de":[0,6],"a":[8,6]}]},{"id":"res","type":"tableau","titre":"Les trois sources d’information","colonnes":["Source","Valeur de U2"],"lignes":[["Calcul à la main","?"],["Simulation","2,50 V"],["Mesure au multimètre","2,43 V"],["Cahier des charges","2,5 V ± 0,15 V"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche l’appareil monté en dérivation, aux bornes de R2.","aide":"Un voltmètre se branche en dérivation, un ampèremètre en série.","type":"zone","document":"cir","multiple":false},{"enonce":"Calcule U2 avec les valeurs nominales des résistances, en volts.","aide":"Pont diviseur : U2 = 5 × R2 / (R1 + R2), avec R1 = R2.","type":"nombre","unite":"V"},{"enonce":"Quel est l’écart relatif entre le calcul et la mesure, en pourcentage ? Arrondis au dixième.","aide":"Écart relatif = (calcul − mesure) / calcul, puis × 100.","type":"nombre","unite":"%"},{"enonce":"Dans le pire cas de la tolérance (R1 à +5 %, R2 à −5 %), quelle valeur minimale prend U2 ? Arrondis au centième de volt.","aide":"R1 = 10,5 kΩ et R2 = 9,5 kΩ ; applique la formule du pont diviseur.","type":"nombre","unite":"V"},{"enonce":"Que conclut Éloïse ?","aide":"Compare la mesure au cahier des charges, puis à l’intervalle de tolérance.","type":"choix","options":[{"id":"a","texte":"Le multimètre est défectueux : il faut en changer"},{"id":"b","texte":"La simulation est fausse : il faut la refaire sans tolérance"},{"id":"c","texte":"Le montage est raté : un écart de mesure est un échec"},{"id":"d","texte":"Le montage est conforme : l’écart s’explique par la tolérance"}],"multiple":false}]}$ex$::jsonb,
