   $ex${"titre":"Une pièce pour contrôler la balance","competence":"lire-tableau","situation":"Nora contrôle la balance du laboratoire avec une pièce de 2 € dont la masse officielle est 8,50 g. Elle la pèse cinq fois de suite.","documents":[{"id":"mesures","type":"tableau","titre":"Cinq pesées de la même pièce","colonnes":["Pesée n°","1","2","3","4","5"],"lignes":[["Masse (g)","8,51","8,50","8,51","8,52","8,51"]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la pesée qui donne la plus grande masse.","aide":"Compare les cinq valeurs au centième de gramme près.","type":"zone","document":"mesures","multiple":false},{"enonce":"Calcule la moyenne des cinq pesées, en grammes.","aide":"Additionne les cinq masses puis divise par 5.","type":"nombre","unite":"g"},{"enonce":"Quel écart sépare cette moyenne de la masse officielle de 8,50 g ? Donne-le en grammes.","aide":"Soustrais la masse officielle à la moyenne.","type":"nombre","unite":"g"},{"enonce":"Les pesées sont toutes proches les unes des autres, et leur moyenne est proche de 8,50 g. Elles sont…","aide":"La fidélité regarde la dispersion ; la justesse regarde l’écart à la référence.","type":"choix","options":[{"id":"a","texte":"fidèles et justes"},{"id":"b","texte":"fidèles mais pas justes"},{"id":"c","texte":"justes mais peu fidèles"},{"id":"d","texte":"ni fidèles ni justes"}],"multiple":false}]}$ex$::jsonb,
