   $ex${"titre":"Le montage à reflux de l’atelier arôme","competence":"observer-schema","situation":"Zoé prépare l’arôme de banane. Le professeur a monté le chauffage à reflux et lui demande de repérer chaque élément avant de lancer le chauffage.","documents":[{"id":"reflux","type":"schema","titre":"Chauffage à reflux, vu de face","largeur":320,"hauteur":305,"elements":[{"forme":"rect","x":100,"y":215,"l":120,"h":50,"arrondi":18,"teinte":"ambre","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":160,"cy":190,"r":46,"teinte":"ciel","motif":"clair","id":"z2","zone":true},{"forme":"ellipse","cx":160,"cy":214,"rx":33,"ry":12,"teinte":"bleu","motif":"clair"},{"forme":"cercle","cx":149,"cy":216,"r":2.5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":163,"cy":219,"r":2.5,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":174,"cy":213,"r":2.5,"teinte":"gris","motif":"plein"},{"forme":"rect","x":150,"y":100,"l":20,"h":46,"teinte":"ciel","motif":"clair"},{"forme":"rect","x":140,"y":18,"l":40,"h":84,"arrondi":4,"teinte":"bleu","motif":"clair","id":"z3","zone":true},{"forme":"ligne","de":[151,18],"a":[151,100],"teinte":"gris"},{"forme":"ligne","de":[169,18],"a":[169,100],"teinte":"gris"},{"forme":"rect","x":106,"y":74,"l":34,"h":12,"arrondi":3,"teinte":"bleu","motif":"plein","id":"z4","zone":true},{"forme":"rect","x":180,"y":34,"l":34,"h":12,"arrondi":3,"teinte":"bleu","motif":"plein","id":"z5","zone":true},{"forme":"rect","x":90,"y":270,"l":140,"h":14,"arrondi":3,"teinte":"gris","motif":"clair"},{"forme":"texte","x":160,"y":299,"texte":"support élévateur","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le réfrigérant.","aide":"C’est le grand tube vertical, au-dessus du ballon, parcouru par de l’eau.","type":"zone","document":"reflux","multiple":false},{"enonce":"Touche le tuyau par lequel l’eau froide doit entrer dans le réfrigérant.","aide":"L’eau doit remplir le manchon de bas en haut : où commence-t-elle ?","type":"zone","document":"reflux","multiple":false},{"enonce":"Associe chaque élément du montage à son rôle.","aide":"Pense à ce qui se passe, de bas en haut, pendant le chauffage.","type":"association","gauche":[{"id":"g0","texte":"Ballon"},{"id":"g1","texte":"Chauffe-ballon"},{"id":"g2","texte":"Réfrigérant"}],"droite":[{"id":"d0","texte":"Chauffe le mélange"},{"id":"d1","texte":"Condense les vapeurs qui retombent"},{"id":"d2","texte":"Contient les réactifs et la pierre ponce"}]}]}$ex$::jsonb,
