  ('aad28990-b793-57bd-9233-a2f7393703d2'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Extraire l’arôme de banane avec l’ampoule à décanter","competence":"experimenter","situation":"Hugo a obtenu l’arôme de banane dissous dans de l’eau. Pour l’en extraire, il choisit un solvant dans le tableau, puis utilise une ampoule à décanter contenant de l’eau et le solvant choisi.","documents":[{"id":"solvants","type":"tableau","titre":"Quatre liquides disponibles","colonnes":["Liquide","ρ (g/mL)","Miscible à l’eau","Dissout l’arôme"],"lignes":[["Eau","1,00","—","non"],["Éthanol","0,79","oui","oui"],["Cyclohexane","0,78","non","oui"],["Dichlorométhane","1,33","non","oui"]],"enteteLignes":true,"source":"Données simplifiées pour l’exercice"},{"id":"ampoule","type":"schema","titre":"L’ampoule après agitation et repos (eau et cyclohexane)","largeur":320,"hauteur":290,"elements":[{"forme":"polygone","points":[[118.5,95],[201.5,95],[215,110],[215,160],[105,160],[105,110]],"teinte":"ciel","motif":"clair","id":"z1","zone":true},{"forme":"polygone","points":[[105,160],[215,160],[215,190],[175,235],[145,235],[105,190]],"teinte":"ciel","motif":"points","id":"z2","zone":true},{"forme":"chemin","d":"M150 20 L170 20 L170 60 L215 110 L215 190 L175 235 L175 262 L145 262 L145 235 L105 190 L105 110 L150 60 Z","ferme":true,"teinte":"gris","motif":"aucun"},{"forme":"rect","x":146,"y":8,"l":28,"h":12,"arrondi":3,"teinte":"brun","motif":"clair"},{"forme":"rect","x":130,"y":244,"l":60,"h":8,"arrondi":2,"teinte":"gris","motif":"plein"},{"forme":"texte","x":160,"y":282,"texte":"ampoule à décanter","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Quels liquides du tableau peuvent servir de solvant extracteur de l’arôme ?","aide":"Un bon extracteur est non miscible à l’eau ET dissout bien l’arôme : cherche les deux « bonnes » colonnes.","type":"choix","options":[{"id":"a","texte":"Éthanol"},{"id":"b","texte":"Cyclohexane"},{"id":"c","texte":"Dichlorométhane"},{"id":"d","texte":"Eau"}],"multiple":true},{"enonce":"Hugo a choisi le cyclohexane. Touche la phase organique, celle qui contient l’arôme.","aide":"Compare la masse volumique du cyclohexane (0,78 g/mL) à celle de l’eau (1,00 g/mL).","type":"zone","document":"ampoule","multiple":false},{"enonce":"Si Hugo avait choisi le dichlorométhane (1,33 g/mL), où serait la phase organique ?","aide":"La position des phases dépend seulement de leurs masses volumiques.","type":"choix","options":[{"id":"a","texte":"En bas, car ce liquide est plus dense que l’eau"},{"id":"b","texte":"En haut, car il n’est pas miscible avec l’eau"},{"id":"c","texte":"En haut, car il dissout mieux l’arôme que l’eau"},{"id":"d","texte":"En bas, car il est plus volatil que l’eau"}],"multiple":false},{"enonce":"Hugo verse 40 mL de cyclohexane dans l’ampoule. Quelle masse de cyclohexane cela représente-t-il ? Réponds en grammes.","aide":"La masse se calcule avec la masse volumique : m = ρ × V.","type":"nombre","unite":"g"},{"enonce":"Range les gestes de l’extraction dans le bon ordre.","aide":"On ne vide jamais une ampoule bouchée : à quel moment ôte-t-on le bouchon ?","type":"ordre","items":[{"id":"a","texte":"Ouvrir le robinet et recueillir la phase du bas"},{"id":"b","texte":"Retourner l’ampoule et agiter en dégazant"},{"id":"c","texte":"Poser l’ampoule sur son support et laisser décanter"},{"id":"d","texte":"Retirer le bouchon"},{"id":"e","texte":"Verser le mélange dans l’ampoule et boucher"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b","c"]},"explication":"Il faut un liquide **non miscible à l’eau** qui **dissout bien l’arôme** : le cyclohexane et le dichlorométhane. L’éthanol se mélange à l’eau ; l’eau ne dissout pas l’arôme."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Le cyclohexane (0,78 g/mL) est **moins dense** que l’eau (1,00 g/mL) : la phase organique flotte, elle est en **haut**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La phase la plus **dense** est en bas : 1,33 g/mL > 1,00 g/mL, donc la phase organique serait **en bas**."},{"cle":{"type":"nombre","valeur":31.2,"tolerance":0.05},"affichage":"31,2 g","explication":"m = ρ × V = 0,78 g/mL × 40 mL = **31,2 g**."},{"cle":{"type":"ordre","ids":["e","b","c","d","a"]},"explication":"On remplit et on bouche, on **agite en dégazant**, on laisse **décanter**, puis on **retire le bouchon** avant d’ouvrir le robinet pour recueillir la phase inférieure."}]$ex$::jsonb),
  ('aad28990-b793-57bd-9233-a2f7393703d2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le protocole de la synthèse de l’acétate d’isoamyle","competence":"analyser-document","situation":"Maëlle va synthétiser l’acétate d’isoamyle. Elle reçoit le protocole du TP et doit comprendre le rôle de chaque étape avant de choisir sa verrerie.","documents":[{"id":"protocole","type":"fiche","modele":"recette","entete":"Protocole du TP","sousTitre":"Synthèse de l’acétate d’isoamyle","emoji":"🍌","lignes":[{"texte":"1. Mettre dans un ballon 10 mL d’alcool isoamylique, 20 mL d’acide éthanoïque, quelques gouttes d’acide sulfurique et de la pierre ponce.","id":"z1"},{"texte":"2. Chauffer à reflux pendant 30 minutes.","id":"z2"},{"texte":"3. Refroidir, verser sur de l’eau salée dans une ampoule, agiter en dégazant, décanter.","id":"z3"},{"texte":"4. Laver la phase organique par une solution d’hydrogénocarbonate de sodium.","id":"z4"},{"texte":"5. Sécher sur sulfate de magnésium anhydre et filtrer.","id":"z5"},{"texte":"6. Distiller et recueillir l’ester.","id":"z6"}],"pied":"Protocole écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’étape où l’ester est séparé de la phase aqueuse par différence de densité, avec de l’eau salée.","aide":"Cherche l’étape qui utilise l’ampoule à décanter.","type":"zone","document":"protocole","multiple":false},{"enonce":"Classe chaque opération dans le temps de la synthèse où elle intervient.","aide":"Transformer : on fait réagir. Isoler : on sépare le produit du milieu. Purifier : on enlève les impuretés restantes.","type":"categories","categories":[{"id":"c0","texte":"Transformer"},{"id":"c1","texte":"Isoler"},{"id":"c2","texte":"Purifier"}],"items":[{"id":"i0","texte":"Chauffage à reflux"},{"id":"i1","texte":"Filtration sous vide"},{"id":"i2","texte":"Décantation en ampoule"},{"id":"i3","texte":"Lavage à l’hydrogénocarbonate"},{"id":"i4","texte":"Distillation"},{"id":"i5","texte":"Séchage sur sulfate de magnésium"}]},{"enonce":"Associe chaque mesure du protocole à la verrerie adaptée.","aide":"Un volume précis demande de la verrerie précise ; un réactif en excès se mesure approximativement.","type":"association","gauche":[{"id":"g0","texte":"20 mL d’acide éthanoïque en excès"},{"id":"g1","texte":"10,0 mL d’alcool isoamylique à doser précisément"},{"id":"g2","texte":"Quelques grammes de sulfate de magnésium"}],"droite":[{"id":"d0","texte":"Éprouvette graduée"},{"id":"d1","texte":"Balance"},{"id":"d2","texte":"Pipette jaugée"}]},{"enonce":"Les réactifs occupent environ 30 mL. Le ballon ne doit être rempli qu’à moitié au plus : quel est le plus petit ballon qui convient ?","aide":"Un ballon de 50 mL ne peut contenir que 25 mL de liquide au plus.","type":"choix","options":[{"id":"a","texte":"50 mL"},{"id":"b","texte":"100 mL"},{"id":"c","texte":"250 mL"},{"id":"d","texte":"500 mL"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"À l’étape **3**, l’eau salée diminue la solubilité de l’ester dans l’eau (relargage) : il se retrouve dans la phase du haut, moins dense, que l’on sépare par décantation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c2","i4":"c2","i5":"c2"}},"explication":"Le **reflux** transforme ; la **décantation** et la **filtration** isolent ; le **lavage**, le **séchage** et la **distillation** purifient."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Un volume **approximatif** (réactif en excès) se prélève à l’**éprouvette**, un volume **précis** à la **pipette jaugée**, un solide se **pèse**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec 30 mL de liquides et un ballon rempli à moitié au plus, il faut une contenance d’au moins 60 mL : le plus petit ballon courant qui convient est celui de **100 mL**."}]$ex$::jsonb),
  ('c3d67f85-7fa1-5f25-8445-4a93b12bdef7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le banc Kofler contrôle l’acide benzoïque","competence":"lire-tableau","situation":"Camille a synthétisé de l’acide benzoïque. Elle mesure sa température de fusion sur un banc Kofler avant et après recristallisation. La valeur tabulée de l’acide benzoïque pur est 122 °C.","documents":[{"id":"fusion","type":"tableau","titre":"Intervalles de fusion mesurés","colonnes":["Échantillon","Début de fusion (°C)","Fin de fusion (°C)"],"lignes":[["Produit brut","116","120"],["Produit recristallisé","121","122"]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la température qui coïncide avec la valeur tabulée de 122 °C.","aide":"Cherche 122 dans le tableau.","type":"zone","document":"fusion","multiple":false},{"enonce":"Quelle est la largeur de l’intervalle de fusion du produit brut, en °C ?","aide":"Soustrais la température de début à celle de fin.","type":"nombre","unite":"°C"},{"enonce":"Que montrent ces mesures ?","aide":"Les impuretés abaissent la température de fusion et l’étalent.","type":"choix","options":[{"id":"a","texte":"Le produit recristallisé est impur : il fond sur un intervalle trop étroit"},{"id":"b","texte":"Le produit brut est plus pur : il fond plus bas et sur un intervalle plus large"},{"id":"c","texte":"Le produit recristallisé est plus pur : il fond plus haut et sur un intervalle plus étroit"},{"id":"d","texte":"Les deux produits sont aussi purs : seule la température de début change"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"C’est la fin de fusion du produit **recristallisé**, **122 °C** : elle égale la valeur tabulée."},{"cle":{"type":"nombre","valeur":4,"tolerance":0.1},"affichage":"4 °C","explication":"120 − 116 = **4 °C**. Un produit pur fond sur un intervalle étroit."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un solide impur fond **plus bas** et sur un **intervalle** plus large ; la recristallisation a **purifié** le produit, qui fond à 121–122 °C."}]$ex$::jsonb),
  ('c3d67f85-7fa1-5f25-8445-4a93b12bdef7'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Lire la plaque de CCM de l’ester","competence":"analyser-document","situation":"Après une estérification, Inès dépose sur une plaque de CCM le réactif, son produit brut et un ester de référence pur. Elle élue, révèle, puis mesure à la règle.","documents":[{"id":"plaque","type":"schema","titre":"La plaque révélée","largeur":320,"hauteur":275,"elements":[{"forme":"rect","x":50,"y":20,"l":220,"h":235,"arrondi":4,"teinte":"gris","motif":"clair"},{"forme":"ligne","de":[50,45],"a":[270,45],"style":"pointilles"},{"forme":"ligne","de":[50,225],"a":[270,225]},{"forme":"texte","x":56,"y":38,"texte":"front du solvant","taille":"petit","italique":true,"ancre":"debut"},{"forme":"texte","x":56,"y":217,"texte":"ligne de dépôt","taille":"petit","italique":true,"ancre":"debut"},{"forme":"ellipse","cx":100,"cy":171,"rx":11,"ry":7,"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"ellipse","cx":160,"cy":171,"rx":11,"ry":7,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"ellipse","cx":160,"cy":99,"rx":11,"ry":7,"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"ellipse","cx":220,"cy":99,"rx":11,"ry":7,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":100,"y":246,"texte":"R","gras":true,"ancre":"milieu"},{"forme":"texte","x":160,"y":246,"texte":"P","gras":true,"ancre":"milieu"},{"forme":"texte","x":220,"y":246,"texte":"Réf.","gras":true,"ancre":"milieu"}],"legende":[{"teinte":"violet","motif":"plein","texte":"tache révélée"}],"source":"R : réactif · P : produit brut · Réf. : ester pur"},{"id":"regle","type":"tableau","titre":"Distances mesurées depuis la ligne de dépôt","colonnes":["Repère","Distance (cm)"],"lignes":[["Front du solvant","6,0"],["Tache du réactif R","1,8"],["Tache du bas de P","1,8"],["Tache du haut de P","4,2"],["Tache de la référence","4,2"]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la tache du produit brut qui prouve qu’il reste du réactif.","aide":"Cherche la tache de P située au même niveau que celle du réactif R.","type":"zone","document":"plaque","multiple":false},{"enonce":"Calcule le rapport frontal de l’ester de référence (distance de la tache / distance du front), sans unité.","aide":"Divise 4,2 cm par 6,0 cm.","type":"nombre"},{"enonce":"Quelle conclusion tirer de la plaque ?","aide":"Compare les niveaux des taches de P avec ceux de R et de la référence.","type":"choix","options":[{"id":"a","texte":"L’ester est bien formé, mais la transformation est incomplète : le produit brut contient du réactif"},{"id":"b","texte":"La transformation est complète : le produit brut ne contient que l’ester de référence"},{"id":"c","texte":"Le produit brut est pur : ses deux taches correspondent à la même espèce"},{"id":"d","texte":"L’ester n’est pas formé : le produit brut ne contient que le réactif de départ"}],"multiple":false}]}$ex$::jsonb,
