  ('84553740-9424-5e81-b623-8e151f93b6e9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Sous les projecteurs de la scène","competence":"raisonner","situation":"Un technicien de théâtre règle des projecteurs de lumière rouge, verte et bleue. Il se demande aussi comment les objets du décor vont paraître selon l’éclairage. Rappel : un projecteur magenta, c’est un mélange de lumière rouge et de lumière bleue.","documents":[{"id":"zones","type":"tableau","titre":"Les quatre zones du plateau","colonnes":["Zone","Projecteurs allumés"],"lignes":[["Zone 1","rouge + vert"],["Zone 2","rouge + bleu"],["Zone 3","vert + bleu"],["Zone 4","rouge + vert + bleu"]],"enteteLignes":true,"source":"Éclairage écrit pour l’exercice"},{"id":"objets","type":"tableau","titre":"Les objets du décor","colonnes":["Objet","Lumières diffusées en lumière blanche"],"lignes":[["Tomate","rouge"],["Feuille de laitue","vert"],["Banane","rouge + vert"],["Mur blanc","rouge + vert + bleu"]],"enteteLignes":true,"source":"Données du cours"}],"questions":[{"enonce":"Associe chaque zone à la couleur de la lumière qu’elle reçoit (synthèse additive).","aide":"En synthèse additive, on ajoute des lumières : relis la liste de chaque zone.","type":"association","gauche":[{"id":"g0","texte":"Zone 1"},{"id":"g1","texte":"Zone 2"},{"id":"g2","texte":"Zone 3"},{"id":"g3","texte":"Zone 4"}],"droite":[{"id":"d0","texte":"Blanc"},{"id":"d1","texte":"Jaune"},{"id":"d2","texte":"Cyan"},{"id":"d3","texte":"Magenta"}]},{"enonce":"Les objets sont éclairés par une lumière bleue pure. Touche ceux qui paraissent noirs.","aide":"Un objet ne diffuse que les lumières qu’il reçoit : lesquels ne contiennent aucune composante bleue ?","type":"zone","document":"objets","multiple":true},{"enonce":"La banane est éclairée par une lumière rouge pure. Elle paraît…","aide":"Elle diffuse la lumière rouge et la lumière verte : laquelle reçoit-elle ici ?","type":"choix","options":[{"id":"a","texte":"rouge"},{"id":"b","texte":"jaune"},{"id":"c","texte":"noire"},{"id":"d","texte":"verte"}],"multiple":false},{"enonce":"Un filtre magenta (il laisse passer les composantes rouge et bleue, il absorbe la composante verte) est placé devant une source blanche. Cette lumière éclaire la feuille de laitue. Elle paraît…","aide":"Quelles composantes la lumière filtrée contient-elle, et laquelle la laitue diffuse-t-elle ?","type":"choix","options":[{"id":"a","texte":"noire"},{"id":"b","texte":"verte"},{"id":"c","texte":"magenta"},{"id":"d","texte":"blanche"}],"multiple":false}]}$ex$::jsonb,
