  ('93495817-b48c-5f4c-943c-49e859698714'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un portrait et un paysage : deux ouvertures","competence":"calculer","situation":"Léa prend deux photos : un portrait avec un arrière-plan flou, puis un paysage net du premier plan à l’horizon. Elle note les réglages de chaque photo.","documents":[{"id":"reglages","type":"tableau","titre":"Les réglages des deux photos","colonnes":["Réglage","Photo A (portrait)","Photo B (paysage)"],"lignes":[["Focale (mm)","85","24"],["Diamètre de l’ouverture (mm)","42,5","3,0"],["Temps de pose","1/1000 s","1/60 s"]],"enteteLignes":true,"source":"Réglages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case du plus grand diamètre d’ouverture.","aide":"Compare les deux diamètres de la ligne « Diamètre de l’ouverture ».","type":"zone","document":"reglages","multiple":false},{"enonce":"Calcule le nombre d’ouverture N de la photo A (N = f′ / D).","aide":"Divise la focale 85 mm par le diamètre 42,5 mm.","type":"nombre"},{"enonce":"Calcule le nombre d’ouverture N de la photo B.","aide":"Divise la focale 24 mm par le diamètre 3,0 mm.","type":"nombre"},{"enonce":"Quelle photo a la plus grande profondeur de champ, et pourquoi ?","aide":"La profondeur de champ augmente quand on ferme le diaphragme.","type":"choix","options":[{"id":"a","texte":"La photo B : le diaphragme est plus fermé (N plus grand)"},{"id":"b","texte":"La photo A : le temps de pose est plus court"},{"id":"c","texte":"La photo B : la focale est plus grande"},{"id":"d","texte":"La photo A : le diaphragme est plus ouvert (N plus petit)"}],"multiple":false},{"enonce":"Léa prend la photo A à f/2 en 1/1000 s. Elle ferme le diaphragme de deux crans (f/2 → f/2,8 → f/4) pour la même exposition. Quel temps de pose, noté 1/___ s, doit-elle choisir ?","aide":"Chaque cran divise la lumière par 2 : de combien faut-il allonger le temps de pose au total ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le diamètre de **42,5 mm** (photo A) est le plus grand : le diaphragme y est très ouvert."},{"cle":{"type":"nombre","valeur":2,"tolerance":0.01},"affichage":"2","explication":"N = 85 / 42,5 = **2** : la photo A est prise à f/2."},{"cle":{"type":"nombre","valeur":8,"tolerance":0.01},"affichage":"8","explication":"N = 24 / 3,0 = **8** : la photo B est prise à f/8."},{"cle":{"type":"choix","ids":["a"]},"explication":"La profondeur de champ **augmente avec N** : f/8 (photo B) donne un paysage net sur tout le champ, f/2 (photo A) un arrière-plan flou."},{"cle":{"type":"nombre","valeur":250,"tolerance":0.5},"affichage":"250","explication":"Chaque cran divise la lumière par 2 : deux crans la divisent par **4**. Il faut un temps 4 fois plus long : 1/1000 s devient **1/250 s**."}]$ex$::jsonb),
  ('93495817-b48c-5f4c-943c-49e859698714'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Photographier un match de handball en salle","competence":"raisonner","situation":"Nina, photographe du club, doit prendre des joueurs situés à 30 m sur le terrain, dans une salle peu éclairée. Elle compare quatre objectifs et le cahier des charges de la séance.","documents":[{"id":"objectifs","type":"tableau","titre":"Les quatre objectifs","colonnes":["Objectif","Focale (mm)","Ouverture maximale"],"lignes":[["A","24","f/2,8"],["B","50","f/1,8"],["C","200","f/2,8"],["D","400","f/5,6"]],"enteteLignes":true,"source":"Objectifs imaginés pour l’exercice"},{"id":"cahier","type":"fiche","modele":"affiche","entete":"Cahier des charges","sousTitre":"Match de handball en salle","emoji":"🤾","lignes":[{"texte":"Sujet","valeur":"joueurs à 30 m, cadrés serrés"},{"texte":"Lumière","valeur":"faible : grande ouverture nécessaire"},{"texte":"Mouvement","valeur":"rapide : pose de 1/500 s au plus"}],"pied":"Cahier des charges écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’objectif qui convient à la fois pour cadrer serré à 30 m et pour travailler avec peu de lumière.","aide":"Il faut une grande focale (angle de champ étroit) ET une grande ouverture (petit nombre N).","type":"zone","document":"objectifs","multiple":false},{"enonce":"Calcule le diamètre maximal d’ouverture de l’objectif C, en mm, arrondi au dixième (N = f′ / D).","aide":"D = f′ / N avec f′ = 200 mm et N = 2,8.","type":"nombre","unite":"mm"},{"enonce":"À f/2,8, Nina obtient la bonne exposition en 1/1000 s. Elle ferme à f/5,6 (deux crans) pour gagner en profondeur de champ. Quel temps de pose, noté 1/___ s, garde la même exposition ?","aide":"Deux crans : la lumière est divisée par 4.","type":"nombre"},{"enonce":"Ce temps de pose de 1/250 s respecte-t-il le cahier des charges ? Que faire ?","aide":"Compare 1/250 s à 1/500 s : lequel est le plus court ?","type":"choix","options":[{"id":"a","texte":"Oui : le cahier des charges ne dit rien sur la vitesse des joueurs"},{"id":"b","texte":"Non : trop long (limite 1/500 s) ; elle reste à f/2,8"},{"id":"c","texte":"Oui : 1/250 s est plus rapide que la limite de 1/500 s, donc il convient"},{"id":"d","texte":"Non : elle doit fermer encore le diaphragme pour raccourcir la pose"}],"multiple":false},{"enonce":"Pour gagner de la lumière sans changer l’ouverture ni le temps de pose, Nina augmente la sensibilité ISO. Quel est l’inconvénient ?","aide":"Une sensibilité élevée amplifie le signal, mais aussi autre chose.","type":"choix","options":[{"id":"a","texte":"Le bruit (le grain) devient plus visible"},{"id":"b","texte":"Le temps de pose doit être allongé"},{"id":"c","texte":"La profondeur de champ diminue"},{"id":"d","texte":"L’angle de champ devient plus étroit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"L’objectif **C** (200 mm, f/2,8) combine une grande focale et une grande ouverture. Le D a la focale mais f/5,6 laisse passer 4 fois moins de lumière ; le B et le A sont trop courts pour cadrer à 30 m."},{"cle":{"type":"nombre","valeur":71.4,"tolerance":0.05},"affichage":"71,4 mm","explication":"D = 200 / 2,8 ≈ **71,4 mm**."},{"cle":{"type":"nombre","valeur":250,"tolerance":0.5},"affichage":"250","explication":"f/2,8 → f/4 → f/5,6 : la lumière est divisée par **4**, le temps de pose est multiplié par 4 : 1/1000 s devient **1/250 s**."},{"cle":{"type":"choix","ids":["b"]},"explication":"1/250 s est **plus long** que 1/500 s : les joueurs rapides seraient flous. Nina garde **f/2,8** et accepte une profondeur de champ réduite."},{"cle":{"type":"choix","ids":["a"]},"explication":"Monter les ISO amplifie le signal **et le bruit** : l’image est plus lumineuse, mais le grain devient plus visible."}]$ex$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Cinq pixels, cinq couleurs","competence":"lire-tableau","situation":"Un logiciel de retouche affiche, pour cinq pixels d’une image, les trois nombres qui décrivent leur couleur : l’intensité de rouge (R), de vert (V) et de bleu (B), chacune codée sur 8 bits.","documents":[{"id":"pixels","type":"tableau","titre":"Codes RVB de cinq pixels","colonnes":["Pixel","R","V","B"],"lignes":[["P1","255","0","0"],["P2","0","0","0"],["P3","255","255","0"],["P4","255","255","255"],["P5","128","128","128"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche le pixel blanc.","aide":"En synthèse additive, la lumière blanche est le mélange des trois lumières à intensité maximale.","type":"zone","document":"pixels","multiple":false},{"enonce":"Associe chaque pixel à sa couleur.","aide":"Un gris a trois composantes égales ; un pixel jaune mélange rouge et vert sans bleu.","type":"association","gauche":[{"id":"g0","texte":"Pixel P1"},{"id":"g1","texte":"Pixel P2"},{"id":"g2","texte":"Pixel P3"},{"id":"g3","texte":"Pixel P5"}],"droite":[{"id":"d0","texte":"Rouge pur"},{"id":"d1","texte":"Gris moyen"},{"id":"d2","texte":"Jaune"},{"id":"d3","texte":"Noir"}]},{"enonce":"Combien d’octets faut-il pour coder un seul pixel en RVB à 8 bits par composante ?","aide":"Trois composantes, 8 bits chacune, et 1 octet = 8 bits.","type":"nombre","unite":"octets"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le blanc s’obtient avec les trois composantes à leur maximum : (255, 255, 255), c’est le pixel **P4**."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"P1 (255, 0, 0) est **rouge pur** ; P2 (0, 0, 0) **noir** ; P3 (255, 255, 0) **jaune** (rouge + vert) ; P5 (128, 128, 128) un **gris moyen**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0.1},"affichage":"3 octets","explication":"3 × 8 = 24 bits, soit **3 octets** par pixel."}]$ex$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Combien de photos tiennent sur la carte mémoire ?","competence":"calculer","situation":"Maya hésite entre deux appareils photo. Elle veut savoir combien de photos non compressées elle pourra stocker sur une carte mémoire de 32 Go (1 Go = 10⁹ octets). Les images sont codées en RVB, 3 octets par pixel.","documents":[{"id":"appareils","type":"tableau","titre":"Les deux appareils","colonnes":["Appareil","Définition (pixels)"],"lignes":[["Appareil A","4 000 × 3 000"],["Appareil B","6 000 × 4 000"]],"enteteLignes":true,"source":"Appareils imaginés pour l’exercice"}],"questions":[{"enonce":"Touche la plus grande définition.","aide":"Compare le nombre total de pixels, pas seulement la largeur.","type":"zone","document":"appareils","multiple":false},{"enonce":"Combien de millions de pixels compte l’image de l’appareil A ?","aide":"Multiplie la largeur par la hauteur, puis exprime en millions.","type":"nombre","unite":"millions"},{"enonce":"Quelle est la taille non compressée d’une image de l’appareil B, en Mo (1 Mo = 10⁶ octets) ?","aide":"Taille = nombre de pixels × 3 octets.","type":"nombre","unite":"Mo"},{"enonce":"Combien d’images non compressées de l’appareil A (36 Mo chacune) tiennent entièrement sur la carte de 32 Go ?","aide":"Convertis 32 Go en Mo (32 000 Mo), puis divise par 36 Mo et garde le nombre entier d’images.","type":"nombre"},{"enonce":"Avec des fichiers JPEG compressés, la même carte contient…","aide":"Que fait la compression JPEG à la taille d’un fichier ?","type":"choix","options":[{"id":"a","texte":"plus de photos, car chaque fichier est plus léger"},{"id":"b","texte":"autant de photos, car le nombre de pixels ne change pas"},{"id":"c","texte":"plus de photos, mais seulement si on diminue la définition"},{"id":"d","texte":"moins de photos, car la compression ajoute des données"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"L’appareil **B** (6 000 × 4 000 = 24 millions de pixels) a la plus grande définition."},{"cle":{"type":"nombre","valeur":12,"tolerance":0.1},"affichage":"12 millions","explication":"4 000 × 3 000 = 12 000 000, soit **12 millions** de pixels."},{"cle":{"type":"nombre","valeur":72,"tolerance":0.5},"affichage":"72 Mo","explication":"24 × 10⁶ pixels × 3 octets = 72 × 10⁶ octets = **72 Mo**."},{"cle":{"type":"nombre","valeur":888,"tolerance":0.5},"affichage":"888","explication":"32 000 / 36 ≈ 888,9 : **888** images entières."},{"cle":{"type":"choix","ids":["a"]},"explication":"La compression JPEG **réduit la taille** des fichiers : la carte contient donc **plus de photos**, parfois au prix d’une perte de qualité."}]$ex$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Envoyer la photo du but depuis le stade","competence":"raisonner","situation":"Rayan photographie un match et veut envoyer sa photo à la rédaction du club. Il compare la taille du fichier et la durée d’envoi selon le réseau disponible.","documents":[{"id":"photo","type":"fiche","modele":"panneau","entete":"La photo à envoyer","sousTitre":"Caractéristiques du fichier","emoji":"⚽","lignes":[{"texte":"Définition","valeur":"3 000 × 2 000 pixels"},{"texte":"Codage","valeur":"RVB, 8 bits par composante"},{"texte":"Fichier JPEG envoyé","valeur":"2,4 Mo","id":"z1"}],"pied":"Fiche écrite pour l’exercice"},{"id":"reseaux","type":"tableau","titre":"Les réseaux disponibles","colonnes":["Réseau","Débit (Mbit/s)"],"lignes":[["Wi-Fi du stade","50"],["4G","20"],["ADSL du club","8"],["Fibre de la rédaction","500"]],"enteteLignes":true,"source":"Débits écrits pour l’exercice"}],"questions":[{"enonce":"Quelle serait la taille de cette image non compressée, en Mo ?","aide":"Nombre de pixels × 3 octets par pixel.","type":"nombre","unite":"Mo"},{"enonce":"Combien de temps dure l’envoi du fichier JPEG de 2,4 Mo en 4G ? Réponds en secondes, arrondi au centième.","aide":"Convertis d’abord 2,4 Mo en bits (× 8), puis divise par le débit en bit/s.","type":"nombre","unite":"s"},{"enonce":"Touche tous les réseaux qui permettent d’envoyer le fichier JPEG en moins d’une seconde.","aide":"Le fichier fait 19,2 Mbit : quel débit faut-il pour l’envoyer en 1 s ?","type":"zone","document":"reseaux","multiple":true},{"enonce":"Un camarade trouve 0,12 s pour l’envoi en 4G. Quelle erreur a-t-il probablement commise ?","aide":"Refais le calcul sans le facteur 8 : 2,4 / 20 donne quelle valeur ?","type":"choix","options":[{"id":"a","texte":"Il a confondu Mo et Go dans la conversion"},{"id":"b","texte":"Il a oublié de convertir les octets en bits (facteur 8)"},{"id":"c","texte":"Il a divisé le débit par la taille au lieu de l’inverse"},{"id":"d","texte":"Il a utilisé la taille non compressée de 18 Mo"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":18,"tolerance":0.1},"affichage":"18 Mo","explication":"3 000 × 2 000 = 6 × 10⁶ pixels ; × 3 octets = 18 × 10⁶ octets = **18 Mo**."},{"cle":{"type":"nombre","valeur":0.96,"tolerance":0.005},"affichage":"0,96 s","explication":"2,4 × 10⁶ octets × 8 = 1,92 × 10⁷ bits ; durée = 1,92 × 10⁷ / (20 × 10⁶) = **0,96 s**."},{"cle":{"type":"zone","ids":["r0c0","r1c0","r3c0"]},"explication":"Le fichier pèse 19,2 Mbit : il faut un débit **supérieur à 19,2 Mbit/s**. Le Wi-Fi (50), la 4G (20) et la fibre (500) conviennent ; l’ADSL (8) met 2,4 s."},{"cle":{"type":"choix","ids":["b"]},"explication":"2,4 / 20 = 0,12 : il a divisé des **octets** par un débit en **bits** par seconde. Il faut multiplier la taille par **8** avant de diviser."}]$ex$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans un thermomètre numérique","competence":"analyser-document","situation":"Le thermomètre numérique du laboratoire affiche la température d’un bain. Le technicien ouvre l’appareil et schématise ce qu’il y trouve, de la grandeur mesurée jusqu’à l’écran.","documents":[{"id":"chaine","type":"chaine","titre":"De la température à l’affichage","disposition":"colonne","noeuds":[{"id":"z1","texte":"Température du bain","emoji":"🌡️"},{"id":"z2","texte":"Thermistance","emoji":"🔌"},{"id":"z3","texte":"Pont diviseur de tension","emoji":"⚡"},{"id":"z4","texte":"Carte d’acquisition (10 bits)","emoji":"🧮"},{"id":"z5","texte":"Affichage de la valeur","emoji":"🖥️"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche l’élément qui joue le rôle de capteur.","aide":"Le capteur est le premier maillon : celui dont une propriété électrique varie avec la température.","type":"zone","document":"chaine","multiple":false},{"enonce":"Associe chaque élément de la chaîne à son rôle.","aide":"Capteur, conditionneur, convertisseur : un rôle chacun, dans cet ordre.","type":"association","gauche":[{"id":"g0","texte":"Thermistance"},{"id":"g1","texte":"Pont diviseur de tension"},{"id":"g2","texte":"Carte d’acquisition"}],"droite":[{"id":"d0","texte":"Fournit une tension exploitable"},{"id":"d1","texte":"Convertit la tension en nombre binaire"},{"id":"d2","texte":"Convertit T en grandeur électrique"}]},{"enonce":"La carte d’acquisition est un CAN de 10 bits. Combien de niveaux de tension distingue-t-elle ?","aide":"Un CAN de n bits découpe sa plage en 2ⁿ niveaux.","type":"nombre","unite":"niveaux"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **thermistance** convertit la température en grandeur électrique : sa résistance varie avec T. C’est le capteur."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **capteur** (thermistance) convertit la grandeur, le **conditionneur** (pont diviseur) donne une tension, le **CAN** (carte d’acquisition) la numérise."},{"cle":{"type":"nombre","valeur":1024,"tolerance":0.5},"affichage":"1024 niveaux","explication":"Un CAN de 10 bits distingue 2¹⁰ = **1 024** niveaux."}]$ex$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Étalonner une thermistance dans l’eau","competence":"experimenter","situation":"Mehdi relie sa thermistance à un conditionneur : la tension de sortie varie avec la température. Pour établir la relation, il plonge le capteur dans de l’eau à plusieurs températures mesurées par un thermomètre de référence.","documents":[{"id":"etal","type":"graphique","forme":"courbe","titre":"Tension de sortie en fonction de la température","categories":["10","20","30","40","50"],"series":[{"nom":"U","valeurs":[0.4,0.5,0.6,0.7,0.8],"teinte":"violet"}],"axeY":{"titre":"Tension U","unite":"V","min":0,"max":1,"pas":0.2},"axeX":{"titre":"Température (°C)"},"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche le point mesuré à 40 °C.","aide":"Les points sont régulièrement espacés : repère l’abscisse 40.","type":"zone","document":"etal","multiple":false},{"enonce":"Calcule la sensibilité du capteur, en mV par °C (variation de la tension / variation de la température).","aide":"Entre 10 °C et 50 °C, la tension passe de 0,40 V à 0,80 V : divise l’écart de tension par l’écart de température, puis convertis en mV.","type":"nombre","unite":"mV/°C"},{"enonce":"Le thermomètre est plongé dans un bain : la tension lue vaut 0,665 V. Quelle est la température, en °C ? (La droite d’étalonnage est U = 0,010 × θ + 0,30, avec U en V.)","aide":"Isole θ : θ = (U − 0,30) / 0,010.","type":"nombre","unite":"°C"},{"enonce":"Le CAN de 10 bits sur 0 – 5 V a un quantum de 4,88 mV. Quelle plus petite variation de température la chaîne peut-elle distinguer, en °C, arrondie au centième ?","aide":"Divise le quantum par la sensibilité (10 mV/°C).","type":"nombre","unite":"°C"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le point d’abscisse **40 °C** donne une tension de 0,70 V."},{"cle":{"type":"nombre","valeur":10,"tolerance":0.1},"affichage":"10 mV/°C","explication":"(0,80 − 0,40) / (50 − 10) = 0,010 V/°C, soit **10 mV/°C**."},{"cle":{"type":"nombre","valeur":36.5,"tolerance":0.05},"affichage":"36,5 °C","explication":"θ = (0,665 − 0,30) / 0,010 = **36,5 °C**."},{"cle":{"type":"nombre","valeur":0.49,"tolerance":0.005},"affichage":"0,49 °C","explication":"4,88 mV / (10 mV/°C) ≈ **0,49 °C** : c’est la résolution en température de la chaîne."}]$ex$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Choisir la chaîne de mesure d’une serre","competence":"raisonner","situation":"Un lycée veut équiper sa serre d’un thermomètre à thermistance. Quatre chaînes de mesure sont proposées. Il faut choisir la moins chère qui respecte le cahier des charges.","documents":[{"id":"cdc","type":"fiche","modele":"affiche","entete":"Cahier des charges","sousTitre":"Thermomètre de serre","emoji":"🌱","lignes":[{"texte":"Étendue de mesure","valeur":"0 à 50 °C"},{"texte":"Résolution attendue","valeur":"0,2 °C au plus","id":"z1"},{"texte":"Tension du capteur","valeur":"U = S × θ + 0,30 V"},{"texte":"Choix","valeur":"la chaîne la moins chère qui convient"}],"pied":"Cahier des charges écrit pour l’exercice"},{"id":"chaines","type":"tableau","titre":"Les quatre chaînes proposées","colonnes":["Chaîne","S (mV/°C)","CAN (bits)","Plage (V)","Prix (€)"],"lignes":[["A","10","10","5","8"],["B","10","12","5","14"],["C","20","10","5","11"],["D","10","10","1","10"]],"enteteLignes":true,"source":"S : sensibilité du capteur. Valeurs écrites pour l’exercice."}],"questions":[{"enonce":"Chaîne A : calcule le quantum du CAN (plage / 2ⁿ) puis la résolution en température (quantum / S). Réponds en °C, arrondie au centième.","aide":"Quantum = 5 V / 1 024 ≈ 4,88 mV ; résolution = quantum / sensibilité.","type":"nombre","unite":"°C"},{"enonce":"Touche les chaînes dont la résolution est de 0,2 °C au plus.","aide":"Calcule pour chaque chaîne : plage / 2ⁿ / S. Les chaînes B et D sont meilleures que A sur un point précis.","type":"zone","document":"chaines","multiple":true},{"enonce":"La chaîne D a un CAN dont la plage est 0 – 1 V. Calcule la tension de sortie du capteur à 50 °C (U = S × θ + 0,30), en volts, pour vérifier que la mesure reste dans la plage.","aide":"S = 10 mV/°C = 0,010 V/°C.","type":"nombre","unite":"V"},{"enonce":"Quelle chaîne faut-il choisir ?","aide":"Parmi les chaînes qui respectent la résolution (et l’étendue), prends la moins chère.","type":"choix","options":[{"id":"a","texte":"Chaîne A"},{"id":"b","texte":"Chaîne B"},{"id":"c","texte":"Chaîne C"},{"id":"d","texte":"Chaîne D"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.49,"tolerance":0.005},"affichage":"0,49 °C","explication":"q = 5 / 1 024 ≈ 4,88 mV ; résolution = 4,88 / 10 ≈ **0,49 °C** : supérieure à 0,2 °C, la chaîne A ne convient pas."},{"cle":{"type":"zone","ids":["r1c0","r3c0"]},"explication":"B : 5 000 / 4 096 / 10 ≈ **0,12 °C**. D : 1 000 / 1 024 / 10 ≈ **0,10 °C**. A (0,49 °C) et C (0,24 °C) dépassent 0,2 °C."},{"cle":{"type":"nombre","valeur":0.8,"tolerance":0.005},"affichage":"0,8 V","explication":"U = 0,010 × 50 + 0,30 = **0,80 V**, inférieure à 1 V : la chaîne D mesure bien jusqu’à 50 °C."},{"cle":{"type":"choix","ids":["d"]},"explication":"B (14 €) et D (10 €) respectent la résolution ; D mesure aussi jusqu’à 50 °C. La moins chère est la chaîne **D**."}]$ex$::jsonb),
  ('30588c6b-33e2-5fbc-8e20-0c35a0e2f713'::uuid, 1, 1, 5, 20, 3,
