  ('6912a692-5037-5348-9dcd-38bb57202202'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une page de cahier de laboratoire à relire","competence":"analyser-document","situation":"Alix prépare des étalons pour un dosage par spectrophotométrie. Sa solution mère a une concentration de 2,0 × 10⁻³ mol/L. Son enseignante relit la page de son cahier de laboratoire.","documents":[{"id":"cahier","type":"fiche","modele":"recette","entete":"Cahier de laboratoire","sousTitre":"Page du 12 novembre","emoji":"📓","lignes":[{"texte":"14 h 05 — Étalon n° 3 : 10,0 mL de solution mère dans une fiole jaugée de 50,0 mL, complétée à l’eau distillée.","id":"z1"},{"texte":"14 h 20 — A(étalon 3) = 0,412 à λ = 630 nm.","id":"z2"},{"texte":"14 h 25 — Cuve rayée : mesure refaite avec une cuve neuve, A = 0,408.","id":"z3"},{"texte":"Le soir — Recopié au propre : A = 0,41. Valeurs brutes effacées pour que la page soit plus jolie.","id":"z4"}],"pied":"Page écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui n’a pas sa place dans un cahier de laboratoire.","aide":"On note les mesures brutes au moment où on les fait : que fait cette ligne des valeurs brutes ?","type":"zone","document":"cahier","multiple":false},{"enonce":"Calcule le facteur de dilution entre la solution mère et l’étalon n° 3 (volume final / volume prélevé).","aide":"On a prélevé 10,0 mL pour obtenir 50,0 mL.","type":"nombre"},{"enonce":"Calcule la concentration de l’étalon n° 3, en 10⁻⁴ mol/L.","aide":"La concentration est divisée par le facteur de dilution : 2,0 × 10⁻³ / 5.","type":"nombre","unite":"× 10⁻⁴ mol/L"},{"enonce":"Comment noter correctement l’incident de la cuve rayée ?","aide":"Le cahier est la mémoire du projet : que doit-on pouvoir retrouver plus tard ?","type":"choix","options":[{"id":"a","texte":"Recopier la moyenne des deux mesures à la place des deux valeurs"},{"id":"b","texte":"Ne noter que la mesure refaite, sans parler de la cuve"},{"id":"c","texte":"Garder les deux mesures datées, avec la raison du changement de cuve"},{"id":"d","texte":"Effacer la première mesure et ne garder que la meilleure"}],"multiple":false}]}$ex$::jsonb,
